```typescript
import { Directive, ElementRef, HostListener } from '@angular/core';

@Directive({
  selector: '[appMultiSelect]'
})
export class MultiSelectDirective {

  constructor(private elementRef: ElementRef) {}

  @HostListener('click', ['$event'])
  onClick(event) {
    const target = event.target;
    if (target.tagName.toLowerCase() === 'button') {
      this.handleButtonClick(target);
    }
  }

  private handleButtonClick(button) {
    button.classList.toggle('selected');
    this.updateSelectedNodes();
  }

  private updateSelectedNodes() {
    const nodesWithClass = document.querySelectorAll('.selected');
    const selectedNodes = [];
    nodesWithClass.forEach(node => {
      const parent = node.parentNode;
      while (parent && !this.isNodeInParent(parent)) {
        parent = parent.parentNode;
      }
      if (!parent || this.isNodeInParent(parent)) {
        selectedNodes.push(this.nodeFromElement(node));
      }
    });
    console.log(selectedNodes); // Log or use the selected nodes
  }

  private isNodeInParent(parent: HTMLElement): boolean {
    return parent.querySelector('.selected') !== null;
  }

  private nodeFromElement(element: HTMLElement): CdkTreeNodeModel {
    return element.closest('.cdk-tree-node');
  }
}
```

